import pandas as pd
import numpy as np
from typing import Dict, Any

def profile_dataset(df: pd.DataFrame) -> Dict[str, Any]:
    profile = {
        "row_count": len(df),
        "column_count": len(df.columns),
        "columns": []
    }
    for col in df.columns:
        col_profile = {
            "name": col,
            "dtype": str(df[col].dtype),
            "missing_count": int(df[col].isnull().sum()),
            "missing_pct": round(df[col].isnull().mean() * 100, 2),
            "unique_count": int(df[col].nunique()),
        }
        if pd.api.types.is_numeric_dtype(df[col]):
            col_profile.update({
                "mean": round(float(df[col].mean()), 4),
                "std": round(float(df[col].std()), 4),
                "min": float(df[col].min()),
                "max": float(df[col].max()),
            })
        profile["columns"].append(col_profile)

    missing_total = df.isnull().sum().sum()
    total_cells = df.shape[0] * df.shape[1]
    profile["quality_score"] = round((1 - missing_total / total_cells) * 100, 2) if total_cells > 0 else 0
    return profile

import pandas as pd
import numpy as np
from typing import Dict, Any, Optional

class DataCleaner:
    def __init__(self, df: pd.DataFrame):
        self.df = df.copy()
        self.report = {"steps": [], "original_shape": df.shape}

    def handle_missing_values(self, strategy: str = "mean") -> 'DataCleaner':
        for col in self.df.select_dtypes(include=[np.number]).columns:
            missing = self.df[col].isnull().sum()
            if missing > 0:
                if strategy == "mean":
                    self.df[col].fillna(self.df[col].mean(), inplace=True)
                elif strategy == "median":
                    self.df[col].fillna(self.df[col].median(), inplace=True)
                elif strategy == "drop":
                    self.df.dropna(subset=[col], inplace=True)
                self.report["steps"].append(f"{col}: {missing} missing → {strategy}")

        for col in self.df.select_dtypes(include=["object"]).columns:
            missing = self.df[col].isnull().sum()
            if missing > 0:
                self.df[col].fillna(self.df[col].mode()[0], inplace=True)
                self.report["steps"].append(f"{col}: {missing} missing → mode")
        return self

    def detect_outliers(self, method: str = "iqr", threshold: float = 1.5) -> 'DataCleaner':
        outlier_counts = {}
        for col in self.df.select_dtypes(include=[np.number]).columns:
            if method == "iqr":
                Q1 = self.df[col].quantile(0.25)
                Q3 = self.df[col].quantile(0.75)
                IQR = Q3 - Q1
                mask = (self.df[col] < Q1 - threshold * IQR) | (self.df[col] > Q3 + threshold * IQR)
                outlier_counts[col] = int(mask.sum())
            elif method == "zscore":
                z_scores = np.abs((self.df[col] - self.df[col].mean()) / self.df[col].std())
                mask = z_scores > 3
                outlier_counts[col] = int(mask.sum())
        self.report["outliers"] = outlier_counts
        return self

    def get_quality_score(self) -> float:
        missing_ratio = self.df.isnull().sum().sum() / (self.df.shape[0] * self.df.shape[1])
        return round((1 - missing_ratio) * 100, 2)

    def clean(self) -> tuple:
        self.report["final_shape"] = self.df.shape
        self.report["quality_score"] = self.get_quality_score()
        return self.df, self.report

import pandas as pd
from typing import Dict, Any

def compare_datasets(df1: pd.DataFrame, df2: pd.DataFrame) -> Dict[str, Any]:
    comparison = {
        "shape_change": {
            "rows": {"before": len(df1), "after": len(df2), "diff": len(df2) - len(df1)},
            "cols": {"before": len(df1.columns), "after": len(df2.columns), "diff": len(df2.columns) - len(df1.columns)}
        },
        "added_columns": list(set(df2.columns) - set(df1.columns)),
        "removed_columns": list(set(df1.columns) - set(df2.columns)),
        "common_columns": list(set(df1.columns) & set(df2.columns)),
        "stats_changes": {}
    }
    for col in comparison["common_columns"]:
        if pd.api.types.is_numeric_dtype(df1[col]) and pd.api.types.is_numeric_dtype(df2[col]):
            comparison["stats_changes"][col] = {
                "mean_change": round(float(df2[col].mean() - df1[col].mean()), 4),
                "std_change": round(float(df2[col].std() - df1[col].std()), 4),
                "missing_change": int(df2[col].isnull().sum() - df1[col].isnull().sum())
            }
    return comparison

