from sklearn.pipeline import Pipeline
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import StandardScaler, MinMaxScaler, OneHotEncoder, LabelEncoder
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.base import BaseEstimator, TransformerMixin
import joblib
from typing import List, Dict, Optional

class FeaturePipelineBuilder:
    def __init__(self):
        self.numeric_cols: List[str] = []
        self.categorical_cols: List[str] = []
        self.text_cols: List[str] = []
        self.numeric_strategy: str = "standard"
        self.pipeline: Optional[Pipeline] = None

    def detect_column_types(self, df: pd.DataFrame) -> 'FeaturePipelineBuilder':
        for col in df.columns:
            if pd.api.types.is_numeric_dtype(df[col]):
                self.numeric_cols.append(col)
            elif df[col].nunique() < 20:
                self.categorical_cols.append(col)
            else:
                self.text_cols.append(col)
        return self

    def set_columns(self, numeric: List[str] = None, categorical: List[str] = None, text: List[str] = None) -> 'FeaturePipelineBuilder':
        if numeric: self.numeric_cols = numeric
        if categorical: self.categorical_cols = categorical
        if text: self.text_cols = text
        return self

    def build(self) -> ColumnTransformer:
        transformers = []
        if self.numeric_cols:
            scaler = StandardScaler() if self.numeric_strategy == "standard" else MinMaxScaler()
            transformers.append(('num', scaler, self.numeric_cols))
        if self.categorical_cols:
            transformers.append(('cat', OneHotEncoder(handle_unknown='ignore', sparse_output=False), self.categorical_cols))
        if self.text_cols:
            for col in self.text_cols:
                transformers.append((f'text_{col}', TfidfVectorizer(max_features=100), col))

        self.pipeline = ColumnTransformer(transformers=transformers, remainder='drop')
        return self.pipeline

    def save(self, path: str):
        joblib.dump(self.pipeline, path)

    @staticmethod
    def load(path: str) -> ColumnTransformer:
        return joblib.load(path)

