FEATURE_STORE_DIR = "data/feature_store"
os.makedirs(FEATURE_STORE_DIR, exist_ok=True)

class FeatureStore:
    def __init__(self, db_session=None):
        self.db = db_session
        self._registry: Dict[str, Dict] = {}

    def register_feature(self, name: str, source_column: str, transform_type: str, description: str = "") -> Dict:
        feature_def = {
            "name": name,
            "source_column": source_column,
            "transform_type": transform_type,
            "description": description,
            "version": 1,
            "created_at": datetime.utcnow().isoformat()
        }
        self._registry[name] = feature_def
        return feature_def

    def compute_feature(self, name: str, df: pd.DataFrame) -> pd.Series:
        if name not in self._registry:
            raise ValueError(f"Feature '{name}' kayitli degil")

        feature_def = self._registry[name]
        source_col = feature_def["source_column"]
        transform = feature_def["transform_type"]

        if transform == "standard_scale":
            result = (df[source_col] - df[source_col].mean()) / df[source_col].std()
        elif transform == "min_max_scale":
            result = (df[source_col] - df[source_col].min()) / (df[source_col].max() - df[source_col].min())
        elif transform == "log_transform":
            result = np.log1p(df[source_col])
        elif transform == "bin_5":
            result = pd.cut(df[source_col], bins=5, labels=False)
        elif transform == "passthrough":
            result = df[source_col]
        else:
            raise ValueError(f"Bilinmeyen transform: {transform}")

        output_path = os.path.join(FEATURE_STORE_DIR, f"{name}_v{feature_def['version']}.parquet")
        result.to_frame().to_parquet(output_path)
        return result

    def get_feature(self, name: str) -> pd.Series:
        if name not in self._registry:
            raise ValueError(f"Feature '{name}' kayitli degil")
        feature_def = self._registry[name]
        path = os.path.join(FEATURE_STORE_DIR, f"{name}_v{feature_def['version']}.parquet")
        return pd.read_parquet(path).iloc[:, 0]

    def list_features(self) -> List[Dict]:
        return list(self._registry.values())

import pandas as pd
import numpy as np
from sklearn.ensemble import RandomForestClassifier, RandomForestRegressor
from sklearn.feature_selection import RFE
from typing import Dict, List, Any, Optional

class FeatureAnalyzer:
    def __init__(self, df: pd.DataFrame, target_col: str):
        self.df = df
        self.target_col = target_col
        self.feature_cols = [c for c in df.select_dtypes(include=[np.number]).columns if c != target_col]
        self.X = df[self.feature_cols].fillna(0)
        self.y = df[target_col]

    def correlation_matrix(self) -> Dict[str, Any]:
        corr = self.df[self.feature_cols + [self.target_col]].corr()
        target_corr = corr[self.target_col].drop(self.target_col).to_dict()
        return {
            "target_correlations": {k: round(v, 4) for k, v in target_corr.items()},
            "high_correlations": [
                {"feature": k, "correlation": round(v, 4)}
                for k, v in target_corr.items() if abs(v) > 0.5
            ]
        }

    def tree_importance(self, task: str = "classification") -> Dict[str, float]:
        if task == "classification":
            model = RandomForestClassifier(n_estimators=100, random_state=42)
        else:
            model = RandomForestRegressor(n_estimators=100, random_state=42)
        model.fit(self.X, self.y)
        importance = dict(zip(self.feature_cols, model.feature_importances_))
        return {k: round(v, 4) for k, v in sorted(importance.items(), key=lambda x: x[1], reverse=True)}

    def rfe_ranking(self, n_features: int = 5, task: str = "classification") -> List[Dict]:
        if task == "classification":
            estimator = RandomForestClassifier(n_estimators=50, random_state=42)
        else:
            estimator = RandomForestRegressor(n_estimators=50, random_state=42)
        rfe = RFE(estimator, n_features_to_select=min(n_features, len(self.feature_cols)))
        rfe.fit(self.X, self.y)
        return [
            {"feature": col, "rank": int(rank), "selected": bool(selected)}
            for col, rank, selected in zip(self.feature_cols, rfe.ranking_, rfe.support_)
        ]

    def full_analysis(self, task: str = "classification") -> Dict[str, Any]:
        return {
            "correlation": self.correlation_matrix(),
            "tree_importance": self.tree_importance(task),
            "rfe_ranking": self.rfe_ranking(task=task)
        }

