import time
from threading import Lock

class ModelCache:
    def __init__(self, ttl_seconds: int = 3600):
        self._cache: Dict[str, Any] = {}
        self._timestamps: Dict[str, float] = {}
        self._ttl = ttl_seconds
        self._lock = Lock()

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key in self._cache:
                if time.time() - self._timestamps[key] < self._ttl:
                    return self._cache[key]
                else:
                    del self._cache[key]
                    del self._timestamps[key]
        return None

    def set(self, key: str, value: Any):
        with self._lock:
            self._cache[key] = value
            self._timestamps[key] = time.time()

    def invalidate(self, key: str = None):
        with self._lock:
            if key:
                self._cache.pop(key, None)
                self._timestamps.pop(key, None)
            else:
                self._cache.clear()
                self._timestamps.clear()

model_cache = ModelCache(ttl_seconds=3600)

def load_production_model(self, model_name: str) -> bool:
    cached = model_cache.get(f"model_{model_name}")
    if cached:
        self._model = cached["model"]
        self._model_version = cached["version"]
        self._model_name = model_name
        return True

    try:
        model_uri = f"models:/{model_name}/Production"
        self._model = mlflow.sklearn.load_model(model_uri)

        client = mlflow.tracking.MlflowClient()
        versions = client.get_latest_versions(model_name, stages=["Production"])
        if versions:
            self._model_version = versions[0].version

        model_cache.set(f"model_{model_name}", {
            "model": self._model,
            "version": self._model_version
        })
        self._model_name = model_name
        return True
    except Exception as e:
        print(f"Model yukleme hatasi: {e}")
        return False

