class ABTestManager:
    def __init__(self):
        self.tests: Dict[str, Dict] = {}
        self.results: Dict[str, List[Dict]] = defaultdict(list)

    def create_test(self, test_name: str, model_a: str, model_b: str, traffic_split: float = 0.8) -> Dict:
        self.tests[test_name] = {
            "name": test_name,
            "model_a": model_a,
            "model_b": model_b,
            "traffic_split": traffic_split,
            "created_at": time.time(),
            "status": "active"
        }
        return self.tests[test_name]

    def route_request(self, test_name: str) -> str:
        if test_name not in self.tests:
            raise ValueError(f"Test '{test_name}' bulunamadi")
        test = self.tests[test_name]
        if random.random() < test["traffic_split"]:
            return test["model_a"]
        return test["model_b"]

    def log_result(self, test_name: str, model_used: str, prediction: Any, actual: Any = None, latency_ms: float = 0):
        self.results[test_name].append({
            "model": model_used,
            "prediction": prediction,
            "actual": actual,
            "latency_ms": latency_ms,
            "timestamp": time.time()
        })

    def get_statistics(self, test_name: str) -> Dict[str, Any]:
        if test_name not in self.results:
            return {"error": "Sonuc bulunamadi"}

        results = self.results[test_name]
        test = self.tests[test_name]

        model_a_results = [r for r in results if r["model"] == test["model_a"]]
        model_b_results = [r for r in results if r["model"] == test["model_b"]]

        stats_data = {
            "test_name": test_name,
            "total_requests": len(results),
            "model_a": {
                "name": test["model_a"],
                "requests": len(model_a_results),
                "avg_latency_ms": np.mean([r["latency_ms"] for r in model_a_results]) if model_a_results else 0
            },
            "model_b": {
                "name": test["model_b"],
                "requests": len(model_b_results),
                "avg_latency_ms": np.mean([r["latency_ms"] for r in model_b_results]) if model_b_results else 0
            }
        }

        a_correct = [r for r in model_a_results if r["actual"] is not None and r["prediction"] == r["actual"]]
        b_correct = [r for r in model_b_results if r["actual"] is not None and r["prediction"] == r["actual"]]

        if model_a_results and model_b_results:
            a_latencies = [r["latency_ms"] for r in model_a_results]
            b_latencies = [r["latency_ms"] for r in model_b_results]
            t_stat, p_value = stats.ttest_ind(a_latencies, b_latencies)
            stats_data["latency_significance"] = {
                "t_statistic": round(float(t_stat), 4),
                "p_value": round(float(p_value), 4),
                "significant": p_value < 0.05
            }

        return stats_data

