from typing import Dict, List, Any, Optional
from collections import deque
from datetime import datetime, timedelta

class PredictionLogger:
    def __init__(self, max_logs: int = 10000):
        self.logs: deque = deque(maxlen=max_logs)

    def log_prediction(self, input_features: Dict, prediction: Any, confidence: float, 
                       model_version: str, latency_ms: float):
        self.logs.append({
            "timestamp": datetime.utcnow().isoformat(),
            "input_features": input_features,
            "prediction": prediction,
            "confidence": confidence,
            "model_version": model_version,
            "latency_ms": latency_ms
        })

    def get_stats(self, minutes: int = 60) -> Dict[str, Any]:
        cutoff = datetime.utcnow() - timedelta(minutes=minutes)
        recent = [l for l in self.logs if datetime.fromisoformat(l["timestamp"]) > cutoff]

        if not recent:
            return {"total_predictions": 0}

        latencies = [l["latency_ms"] for l in recent]
        confidences = [l["confidence"] for l in recent]
        predictions = [l["prediction"] for l in recent]

        return {
            "total_predictions": len(recent),
            "period_minutes": minutes,
            "latency": {
                "avg": round(np.mean(latencies), 2),
                "p50": round(np.percentile(latencies, 50), 2),
                "p95": round(np.percentile(latencies, 95), 2),
                "p99": round(np.percentile(latencies, 99), 2),
                "max": round(max(latencies), 2)
            },
            "confidence": {
                "avg": round(np.mean(confidences), 4),
                "min": round(min(confidences), 4),
                "low_confidence_count": sum(1 for c in confidences if c < 0.5)
            },
            "prediction_distribution": {
                str(k): predictions.count(k) for k in set(predictions)
            }
        }

