    def __init__(self):
        self.baseline_stats: Dict[str, Dict] = {}

    def set_baseline(self, df: pd.DataFrame, feature_columns: List[str]):
        for col in feature_columns:
            if pd.api.types.is_numeric_dtype(df[col]):
                self.baseline_stats[col] = {
                    "values": df[col].dropna().values,
                    "mean": float(df[col].mean()),
                    "std": float(df[col].std()),
                    "min": float(df[col].min()),
                    "max": float(df[col].max())
                }

    def detect_drift_ks(self, current_df: pd.DataFrame, threshold: float = 0.05) -> Dict[str, Any]:
        results = {"drifted_features": [], "feature_results": {}, "overall_drift": False}

        for col, baseline in self.baseline_stats.items():
            if col not in current_df.columns:
                continue
            current_values = current_df[col].dropna().values
            if len(current_values) == 0:
                continue

            statistic, p_value = ks_2samp(baseline["values"], current_values)
            is_drifted = p_value < threshold

            results["feature_results"][col] = {
                "ks_statistic": round(float(statistic), 4),
                "p_value": round(float(p_value), 6),
                "drifted": is_drifted,
                "baseline_mean": round(baseline["mean"], 4),
                "current_mean": round(float(current_df[col].mean()), 4),
                "mean_shift": round(float(current_df[col].mean()) - baseline["mean"], 4)
            }
            if is_drifted:
                results["drifted_features"].append(col)

        results["overall_drift"] = len(results["drifted_features"]) > 0
        results["drift_ratio"] = len(results["drifted_features"]) / max(len(self.baseline_stats), 1)
        return results

    def calculate_psi(self, baseline: np.ndarray, current: np.ndarray, bins: int = 10) -> float:
        baseline_counts, bin_edges = np.histogram(baseline, bins=bins)
        current_counts, _ = np.histogram(current, bins=bin_edges)

        baseline_pct = (baseline_counts + 1) / (len(baseline) + bins)
        current_pct = (current_counts + 1) / (len(current) + bins)

        psi = np.sum((current_pct - baseline_pct) * np.log(current_pct / baseline_pct))
        return round(float(psi), 4)

    def detect_drift_psi(self, current_df: pd.DataFrame, psi_threshold: float = 0.2) -> Dict[str, Any]:
        results = {"drifted_features": [], "feature_results": {}}

        for col, baseline in self.baseline_stats.items():
            if col not in current_df.columns:
                continue
            current_values = current_df[col].dropna().values
            if len(current_values) == 0:
                continue

            psi = self.calculate_psi(baseline["values"], current_values)
            is_drifted = psi > psi_threshold

            results["feature_results"][col] = {
                "psi": psi,
                "drifted": is_drifted,
                "interpretation": "significant shift" if psi > 0.25 else "moderate shift" if psi > 0.1 else "no shift"
            }
            if is_drifted:
                results["drifted_features"].append(col)

        results["overall_drift"] = len(results["drifted_features"]) > 0
        return results

