from typing import Dict, Any, Optional
from datetime import datetime

class AutoRetrainManager:
    def __init__(self):
        self.config = {
            "enabled": False,
            "drift_threshold": 0.05,
            "performance_drop_threshold": 0.05,
            "min_samples_for_retrain": 100,
            "auto_promote": False,
            "validation_accuracy_min": 0.80
        }
        self.retrain_history: list = []

    def configure(self, **kwargs):
        self.config.update(kwargs)
        return self.config

    def should_retrain(self, drift_result: Dict, performance_result: Dict) -> Dict[str, Any]:
        reasons = []

        if drift_result.get("overall_drift", False):
            drifted = drift_result.get("drifted_features", [])
            reasons.append(f"Data drift detected in: {', '.join(drifted)}")

        if performance_result.get("degraded", False):
            drop = performance_result.get("accuracy_drop", 0)
            reasons.append(f"Performance degradation: accuracy dropped by {drop:.2%}")

        should = len(reasons) > 0 and self.config["enabled"]

        return {
            "should_retrain": should,
            "reasons": reasons,
            "auto_retrain_enabled": self.config["enabled"],
            "timestamp": datetime.utcnow().isoformat()
        }

    def validate_new_model(self, new_accuracy: float, old_accuracy: float) -> Dict[str, Any]:
        is_better = new_accuracy > old_accuracy
        meets_minimum = new_accuracy >= self.config["validation_accuracy_min"]
        approved = is_better and meets_minimum

        result = {
            "approved": approved,
            "new_accuracy": round(new_accuracy, 4),
            "old_accuracy": round(old_accuracy, 4),
            "improvement": round(new_accuracy - old_accuracy, 4),
            "meets_minimum_threshold": meets_minimum,
            "auto_promote": approved and self.config["auto_promote"]
        }

        self.retrain_history.append({
            **result,
            "timestamp": datetime.utcnow().isoformat()
        })

        return result

auto_retrain_manager = AutoRetrainManager()

