from typing import Dict, List, Any, Optional
from datetime import datetime
import json
import os

class ModelCard:
    def __init__(self, model_name: str):
        self.card = {
            "model_name": model_name,
            "created_at": datetime.utcnow().isoformat(),
            "model_details": {},
            "intended_use": {},
            "training_data": {},
            "performance_metrics": {},
            "limitations": [],
            "ethical_considerations": [],
            "version_history": []
        }

    def set_model_details(self, model_type: str, framework: str, version: str, description: str):
        self.card["model_details"] = {
            "type": model_type,
            "framework": framework,
            "version": version,
            "description": description
        }
        return self

    def set_intended_use(self, primary_use: str, users: List[str], out_of_scope: List[str]):
        self.card["intended_use"] = {
            "primary_use": primary_use,
            "intended_users": users,
            "out_of_scope_uses": out_of_scope
        }
        return self

    def set_training_data(self, description: str, size: int, features: List[str], preprocessing: str):
        self.card["training_data"] = {
            "description": description,
            "size": size,
            "features": features,
            "preprocessing": preprocessing
        }
        return self

    def set_metrics(self, metrics: Dict[str, float]):
        self.card["performance_metrics"] = metrics
        return self

    def add_limitation(self, limitation: str):
        self.card["limitations"].append(limitation)
        return self

    def save(self, output_dir: str = "model_cards"):
        os.makedirs(output_dir, exist_ok=True)
        path = os.path.join(output_dir, f"{self.card['model_name']}_card.json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(self.card, f, indent=2, ensure_ascii=False)
        return path

    def to_markdown(self) -> str:
        md = f"# Model Card: {self.card['model_name']}\n\n"
        md += f"**Olusturulma Tarihi:** {self.card['created_at']}\n\n"
        md += "## Model Detaylari\n"
        for k, v in self.card['model_details'].items():
            md += f"- **{k}:** {v}\n"
        md += "\n## Performans Metrikleri\n"
        for k, v in self.card['performance_metrics'].items():
            md += f"- **{k}:** {v}\n"
        md += "\n## Limitasyonlar\n"
        for l in self.card['limitations']:
            md += f"- {l}\n"
        return md
